import react from "react";
import { Link } from "react-router-dom";
import "./nav.css"
const Nav = () => {
    return (
        <>
            <div className="navi">

        <Link className="kk" to='/'>Home</Link>
        <Link to='/about'>About</Link>
                <Link to='/contact'>Contact</Link>
        <Link to='/blo'></Link>
</div>
        </>
    )
}

export default Nav
